// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {StaxLPStaking} from "../src/StaxLPStaking.sol";

contract InvMutTest is Test {
    StaxLPStaking c;
    function setUp() public { c = new StaxLPStaking(address(new __InvMutHandleStub()), address(new __InvMutHandleStub())); }
    function testFuzz_property(address newOwner) public {
        bool ok;
        try c.transferOwnership(newOwner) { ok = true; } catch { ok = false; }
        // General rule: any successful ownership transfer leaves a NON-ZERO owner.
        // The reference reverts when newOwner == address(0), so owner() is never 0 after success.
        // The mutant succeeds with newOwner == address(0), leaving owner() == address(0).
        assertTrue(!ok || c.owner() != address(0));
    }
}
